import React, { useState, useEffect, useRef, useCallback } from 'react';
import ReactMarkdown from 'react-markdown';
import {
  Send,
  Database,
  Upload,
  RefreshCw,
  Trash2,
  Image as ImageIcon,
  ChevronRight,
  AlertCircle,
  CheckCircle,
  Loader2,
  Menu,
  X,
  FlaskConical,
  BarChart3,
  Settings,
  MessageSquare,
  Table,
  Beaker,
  Thermometer,
  DollarSign,
  AlertTriangle
} from 'lucide-react';

// API Configuration
const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:8000';

// ============================================================
// API Functions
// ============================================================

const api = {
  async getStatus() {
    const res = await fetch(`${API_BASE}/api/status`);
    return res.json();
  },

  async chat(message, sessionId) {
    const res = await fetch(`${API_BASE}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message, session_id: sessionId })
    });
    return res.json();
  },

  async getTables() {
    const res = await fetch(`${API_BASE}/api/tables`);
    return res.json();
  },

  async reindex() {
    const res = await fetch(`${API_BASE}/api/reindex`, { method: 'POST' });
    return res.json();
  },

  async uploadFile(file) {
    const formData = new FormData();
    formData.append('file', file);
    const res = await fetch(`${API_BASE}/api/upload`, {
      method: 'POST',
      body: formData
    });
    return res.json();
  },

  async getPlots() {
    const res = await fetch(`${API_BASE}/api/plots`);
    return res.json();
  },

  async clearPlots() {
    const res = await fetch(`${API_BASE}/api/plots`, { method: 'DELETE' });
    return res.json();
  },

  async clearSession(sessionId) {
    const res = await fetch(`${API_BASE}/api/session/${sessionId}`, { method: 'DELETE' });
    return res.json();
  },

  async reportIssue(report) {
    const res = await fetch(`${API_BASE}/api/report-issue`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(report)
    });
    return res.json();
  }
};

