// Components
// ============================================================

// Status Badge Component
function StatusBadge({ status }) {
  const isReady = status === 'ready';
  return (
    <div className={`flex items-center gap-2 px-3 py-1.5 rounded-full text-sm ${
      isReady ? 'bg-emerald-500/20 text-emerald-400' : 'bg-amber-500/20 text-amber-400'
    }`}>
      {isReady ? <CheckCircle size={14} /> : <AlertCircle size={14} />}
      {isReady ? 'Ready' : 'Limited'}
    </div>
  );
}

// Message Component
function Message({ message, isUser, onReportIssue }) {
  return (
    <div className={`flex gap-3 ${isUser ? 'flex-row-reverse' : ''}`}>
      <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 ${
        isUser ? 'bg-primary-600' : 'bg-slate-700'
      }`}>
        {isUser ? (
          <span className="text-sm font-medium">You</span>
        ) : (
          <FlaskConical size={16} />
        )}
      </div>
      <div className={`flex-1 max-w-[85%] ${isUser ? 'text-right' : ''}`}>
        <div className={`inline-block rounded-2xl px-4 py-3 ${
          isUser
            ? 'bg-primary-600 text-white'
            : 'bg-slate-800 text-slate-100'
        }`}>
          {isUser ? (
            <p className="whitespace-pre-wrap">{message.content}</p>
          ) : (
            <div className="markdown-content">
              <ReactMarkdown>{message.content}</ReactMarkdown>
            </div>
          )}
        </div>
        {message.images && message.images.length > 0 && (
          <div className="mt-3 flex flex-wrap gap-2">
            {message.images.map((img, i) => (
              <a
                key={i}
                href={`${API_BASE}/plots/${img}`}
                target="_blank"
                rel="noopener noreferrer"
                className="block"
              >
                <img
                  src={`${API_BASE}/plots/${img}`}
                  alt={`Plot ${i + 1}`}
                  className="rounded-lg max-w-xs border border-slate-700 hover:border-primary-500 transition-colors"
                />
              </a>
            ))}
          </div>
        )}
        {message.elapsed && (
          <div className="flex items-center gap-2 mt-1">
            <p className="text-xs text-slate-500">
              {message.elapsed.toFixed(1)}s • {message.iterations} iterations
            </p>
            {!isUser && onReportIssue && (
              <button
                onClick={() => onReportIssue(message)}
                className="flex items-center gap-1 text-xs text-slate-500 hover:text-amber-400 transition-colors"
                title="Report an issue with this response"
              >
                <AlertTriangle size={12} />
                Report
              </button>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

