// Issue Report Modal
function IssueReportModal({ isOpen, onClose, message, userQuestion, onSubmit }) {
  const [description, setDescription] = useState('');
  const [issueType, setIssueType] = useState('incorrect_response');
  const [severity, setSeverity] = useState('medium');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [result, setResult] = useState(null);

  const issueTypes = [
    { value: 'incorrect_response', label: 'Incorrect Response' },
    { value: 'ui_bug', label: 'UI Bug' },
    { value: 'api_error', label: 'API Error' },
    { value: 'performance', label: 'Performance Issue' },
    { value: 'data_issue', label: 'Data Issue' },
    { value: 'other', label: 'Other' },
  ];

  const severities = [
    { value: 'low', label: 'Low' },
    { value: 'medium', label: 'Medium' },
    { value: 'high', label: 'High' },
    { value: 'critical', label: 'Critical' },
  ];

  const handleSubmit = async () => {
    if (!description.trim()) return;

    setIsSubmitting(true);
    setResult(null);

    try {
      const report = {
        user_question: userQuestion || '',
        assistant_response: message?.content || '',
        elapsed_time: message?.elapsed || 0,
        iterations: message?.iterations || 0,
        images: (message?.images || []).map(img => ({
          filename: img,
          base64: '' // Images are referenced by filename, not embedded
        })),
        user_description: description,
        issue_type: issueType,
        severity: severity,
      };

      const response = await onSubmit(report);
      setResult(response);
    } catch (error) {
      setResult({ success: false, error: error.message });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    setDescription('');
    setIssueType('incorrect_response');
    setSeverity('medium');
    setResult(null);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
      <div className="bg-slate-800 rounded-xl max-w-lg w-full max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between p-4 border-b border-slate-700">
          <h2 className="font-semibold text-lg flex items-center gap-2">
            <AlertTriangle size={20} className="text-amber-400" />
            Report Issue
          </h2>
          <button onClick={handleClose} className="p-1 hover:bg-slate-700 rounded">
            <X size={20} />
          </button>
        </div>

        <div className="p-4 space-y-4">
          {!result ? (
            <>
              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">
                  Issue Type
                </label>
                <select
                  value={issueType}
                  onChange={(e) => setIssueType(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:ring-2 focus:ring-primary-500"
                >
                  {issueTypes.map(type => (
                    <option key={type.value} value={type.value}>{type.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">
                  Severity
                </label>
                <div className="flex gap-2">
                  {severities.map(sev => (
                    <button
                      key={sev.value}
                      onClick={() => setSeverity(sev.value)}
                      className={`px-3 py-1.5 rounded-lg text-sm transition-colors ${
                        severity === sev.value
                          ? 'bg-primary-600 text-white'
                          : 'bg-slate-700 text-slate-300 hover:bg-slate-600'
                      }`}
                    >
                      {sev.label}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-300 mb-2">
                  Describe the Issue *
                </label>
                <textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="What went wrong? What did you expect to happen?"
                  rows={4}
                  className="w-full bg-slate-900 border border-slate-700 rounded-lg px-3 py-2 text-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-primary-500 resize-none"
                />
              </div>

              <div className="bg-slate-900 rounded-lg p-3 text-sm text-slate-400">
                <p className="font-medium text-slate-300 mb-1">What happens when you submit:</p>
                <ul className="list-disc list-inside space-y-1">
                  <li>AI analyzes the issue against the codebase</li>
                  <li>A diagnosis with root cause is generated</li>
                  <li>If fixable, a GitHub PR is automatically created</li>
                </ul>
              </div>

              <div className="flex justify-end gap-3 pt-2">
                <button
                  onClick={handleClose}
                  className="px-4 py-2 text-slate-300 hover:text-white transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleSubmit}
                  disabled={!description.trim() || isSubmitting}
                  className="flex items-center gap-2 px-4 py-2 bg-primary-600 hover:bg-primary-700 disabled:bg-slate-700 disabled:text-slate-500 rounded-lg transition-colors"
                >
                  {isSubmitting ? (
                    <>
                      <Loader2 size={16} className="animate-spin" />
                      Analyzing...
                    </>
                  ) : (
                    <>
                      <Send size={16} />
                      Submit Report
                    </>
                  )}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-4">
              <div className={`flex items-start gap-3 p-4 rounded-lg ${
                result.success ? 'bg-emerald-500/20' : 'bg-red-500/20'
              }`}>
                {result.success ? (
                  <CheckCircle className="text-emerald-400 flex-shrink-0 mt-0.5" size={20} />
                ) : (
                  <AlertCircle className="text-red-400 flex-shrink-0 mt-0.5" size={20} />
                )}
                <div>
                  <p className={`font-medium ${result.success ? 'text-emerald-400' : 'text-red-400'}`}>
                    {result.success ? 'Issue Reported Successfully' : 'Report Failed'}
                  </p>
                  <p className="text-sm text-slate-300 mt-1">{result.message}</p>
                </div>
              </div>

              {result.pr_url && (
                <div className="bg-slate-900 rounded-lg p-4">
                  <p className="text-sm text-slate-400 mb-2">A fix has been proposed:</p>
                  <a
                    href={result.pr_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-2 text-primary-400 hover:text-primary-300"
                  >
                    <ChevronRight size={16} />
                    View Pull Request #{result.pr_number}
                  </a>
                </div>
              )}

              {result.diagnosis && (
                <div className="bg-slate-900 rounded-lg p-4 space-y-2">
                  <p className="text-sm font-medium text-slate-300">Diagnosis:</p>
                  <p className="text-sm text-slate-400">{result.diagnosis.summary}</p>
                  {result.diagnosis.root_cause && (
                    <>
                      <p className="text-sm font-medium text-slate-300 mt-2">Root Cause:</p>
                      <p className="text-sm text-slate-400">{result.diagnosis.root_cause}</p>
                    </>
                  )}
                </div>
              )}

              <div className="flex justify-end pt-2">
                <button
                  onClick={handleClose}
                  className="px-4 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg transition-colors"
                >
                  Close
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

