function App() {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [sessionId, setSessionId] = useState(null);
  const [status, setStatus] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notification, setNotification] = useState(null);
  const [issueModalOpen, setIssueModalOpen] = useState(false);
  const [issueMessage, setIssueMessage] = useState(null);
  const [issueContext, setIssueContext] = useState({ userQuestion: '' });

  const messagesEndRef = useRef(null);
  const inputRef = useRef(null);

  // Load status on mount
  useEffect(() => {
    loadStatus();
  }, []);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Focus input after loading
  useEffect(() => {
    if (!isLoading) {
      inputRef.current?.focus();
    }
  }, [isLoading]);

  const loadStatus = async () => {
    try {
      const data = await api.getStatus();
      setStatus(data);
    } catch (e) {
      console.error('Failed to load status:', e);
    }
  };

  const showNotification = (message, type = 'info') => {
    setNotification({ message, type });
    setTimeout(() => setNotification(null), 3000);
  };

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = {
      role: 'user',
      content: input.trim(),
      timestamp: new Date().toISOString()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const response = await api.chat(userMessage.content, sessionId);

      if (!sessionId && response.session_id) {
        setSessionId(response.session_id);
      }

      const assistantMessage = {
        role: 'assistant',
        content: response.response,
        images: response.images,
        elapsed: response.elapsed_time,
        iterations: response.iterations,
        timestamp: new Date().toISOString()
      };

      setMessages(prev => [...prev, assistantMessage]);
    } catch (e) {
      console.error('Chat error:', e);
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: `Error: ${e.message}. Please try again.`,
        timestamp: new Date().toISOString()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleQuickAction = (prompt) => {
    setInput(prompt);
    inputRef.current?.focus();
  };

  const handleReindex = async () => {
    try {
      await api.reindex();
      await loadStatus();
      showNotification('Data reindexed successfully', 'success');
    } catch (e) {
      showNotification('Failed to reindex data', 'error');
    }
  };

  const handleUpload = async (file) => {
    try {
      await api.uploadFile(file);
      await loadStatus();
      showNotification(`Uploaded ${file.name} successfully`, 'success');
    } catch (e) {
      showNotification('Failed to upload file', 'error');
    }
  };

  const handleClearPlots = async () => {
    try {
      await api.clearPlots();
      showNotification('Plots cleared', 'success');
    } catch (e) {
      showNotification('Failed to clear plots', 'error');
    }
  };

  const handleClearChat = async () => {
    if (sessionId) {
      await api.clearSession(sessionId);
    }
    setMessages([]);
    setSessionId(null);
  };

  const handleReportIssue = useCallback((message) => {
    // Find the preceding user message for context
    const msgIndex = messages.findIndex(m => m === message);
    let userQuestion = '';
    if (msgIndex > 0) {
      for (let i = msgIndex - 1; i >= 0; i--) {
        if (messages[i].role === 'user') {
          userQuestion = messages[i].content;
          break;
        }
      }
    }

    setIssueMessage(message);
    setIssueContext({ userQuestion });
    setIssueModalOpen(true);
  }, [messages]);

  const handleSubmitIssue = useCallback(async (report) => {
